const test = require('node:test');
const assert = require('node:assert/strict');

const config = require('../src/config');
const gameState = require('../src/gameState');

test('createInitialState returns Ready status with zeroed score, full time, and no target', () => {
  const state = gameState.createInitialState(config);
  assert.equal(state.status, gameState.STATUS.READY);
  assert.equal(state.score, 0);
  assert.equal(state.timeRemaining, config.ROUND_DURATION_SECONDS);
  assert.equal(state.target, null);
});

test('start transitions to Playing with a reset score/time and the given target', () => {
  const initial = gameState.createInitialState(config);
  const target = { x: 1, y: 2, size: 48 };
  const state = gameState.start(initial, config, target);
  assert.equal(state.status, gameState.STATUS.PLAYING);
  assert.equal(state.score, 0);
  assert.equal(state.timeRemaining, config.ROUND_DURATION_SECONDS);
  assert.deepEqual(state.target, target);
});

test('hit increments score by the configured amount and relocates the target while Playing', () => {
  const initial = gameState.createInitialState(config);
  let state = gameState.start(initial, config, { x: 0, y: 0, size: 48 });
  const newTarget = { x: 10, y: 20, size: 48 };
  state = gameState.hit(state, config, newTarget);
  assert.equal(state.score, config.SCORE_PER_HIT);
  assert.deepEqual(state.target, newTarget);
  assert.equal(state.status, gameState.STATUS.PLAYING);
});

test('hit outside Playing does not change score or target', () => {
  const readyState = gameState.createInitialState(config);
  const attempted = gameState.hit(readyState, config, { x: 5, y: 5, size: 48 });
  assert.equal(attempted.score, 0);
  assert.equal(attempted.target, null);
});

test('tick decrements remaining time by one while Playing and never goes below zero', () => {
  let state = gameState.start(gameState.createInitialState(config), config, { x: 0, y: 0, size: 48 });
  state = Object.assign({}, state, { timeRemaining: 1 });
  state = gameState.tick(state);
  assert.equal(state.timeRemaining, 0);
  state = gameState.tick(state);
  assert.equal(state.timeRemaining, 0);
});

test('tick outside Playing does not change remaining time', () => {
  const readyState = gameState.createInitialState(config);
  const attempted = gameState.tick(readyState);
  assert.equal(attempted.timeRemaining, config.ROUND_DURATION_SECONDS);
});

test('expire transitions to Game Over, clears the target, and preserves the final score', () => {
  let state = gameState.start(gameState.createInitialState(config), config, { x: 0, y: 0, size: 48 });
  state = gameState.hit(state, config, { x: 1, y: 1, size: 48 });
  state = Object.assign({}, state, { timeRemaining: 0 });
  state = gameState.expire(state);
  assert.equal(state.status, gameState.STATUS.GAME_OVER);
  assert.equal(state.target, null);
  assert.equal(state.score, 1);
});

test('restart from Game Over starts a clean Playing round', () => {
  let state = gameState.start(gameState.createInitialState(config), config, { x: 0, y: 0, size: 48 });
  state = gameState.hit(state, config, { x: 1, y: 1, size: 48 });
  state = gameState.expire(state);
  const newTarget = { x: 3, y: 4, size: 48 };
  state = gameState.restart(state, config, newTarget);
  assert.equal(state.status, gameState.STATUS.PLAYING);
  assert.equal(state.score, 0);
  assert.equal(state.timeRemaining, config.ROUND_DURATION_SECONDS);
  assert.deepEqual(state.target, newTarget);
});
