const test = require('node:test');
const assert = require('node:assert/strict');

const placement = require('../src/placement');

test('placement stays within bounds across a range of live play-area sizes', () => {
  const targetSize = 48;
  const sizes = [
    { width: 320, height: 480 },
    { width: 375, height: 600 },
    { width: 800, height: 500 },
    { width: 1920, height: 1080 },
    { width: 48, height: 48 }
  ];

  for (const size of sizes) {
    for (let i = 0; i < 25; i += 1) {
      const position = placement.computeTargetPosition({
        width: size.width,
        height: size.height,
        targetSize: targetSize,
        random: Math.random
      });
      assert.ok(position.x >= 0);
      assert.ok(position.y >= 0);
      assert.ok(position.x + targetSize <= size.width);
      assert.ok(position.y + targetSize <= size.height);
    }
  }
});

test('placement recalculates bounds from the dimensions supplied at each call rather than caching them', () => {
  const targetSize = 48;
  const small = placement.computeTargetPosition({ width: 100, height: 100, targetSize, random: () => 1 });
  const large = placement.computeTargetPosition({ width: 1000, height: 1000, targetSize, random: () => 1 });
  assert.equal(small.x, 52);
  assert.equal(small.y, 52);
  assert.equal(large.x, 952);
  assert.equal(large.y, 952);
});

test('placement clamps extreme random values to the valid inclusive range', () => {
  const targetSize = 48;
  const atMin = placement.computeTargetPosition({ width: 200, height: 200, targetSize, random: () => 0 });
  const atMax = placement.computeTargetPosition({ width: 200, height: 200, targetSize, random: () => 0.999999 });
  assert.equal(atMin.x, 0);
  assert.equal(atMin.y, 0);
  assert.ok(atMax.x <= 152);
  assert.ok(atMax.y <= 152);
});

test('placement returns the requested target size unchanged', () => {
  const position = placement.computeTargetPosition({ width: 300, height: 300, targetSize: 48, random: () => 0.5 });
  assert.equal(position.size, 48);
});
