const test = require('node:test');
const assert = require('node:assert/strict');

const { createGameController } = require('../src/gameController');
const gameState = require('../src/gameState');

class FakeElement {
  constructor() {
    this._listeners = new Map();
  }

  addEventListener(type, handler) {
    if (!this._listeners.has(type)) {
      this._listeners.set(type, new Set());
    }
    this._listeners.get(type).add(handler);
  }

  removeEventListener(type, handler) {
    const set = this._listeners.get(type);
    if (set) {
      set.delete(handler);
    }
  }

  dispatchEvent(event) {
    const set = this._listeners.get(event.type);
    if (!set) {
      return;
    }
    for (const handler of Array.from(set)) {
      handler(event);
    }
  }

  totalListenerCount() {
    let total = 0;
    for (const set of this._listeners.values()) {
      total += set.size;
    }
    return total;
  }
}

function makeEvent(type, extra) {
  return Object.assign(
    {
      type: type,
      defaultPrevented: false,
      preventDefault() {
        this.defaultPrevented = true;
      }
    },
    extra || {}
  );
}

function sequenceRandom(values) {
  let index = 0;
  return function next() {
    const value = values[index % values.length];
    index += 1;
    return value;
  };
}

function createFakeView() {
  const startEl = new FakeElement();
  const targetEl = new FakeElement();
  const playAgainEl = new FakeElement();
  const renders = [];

  return {
    startEl,
    targetEl,
    playAgainEl,
    renders,
    totalListenerCount() {
      return startEl.totalListenerCount() + targetEl.totalListenerCount() + playAgainEl.totalListenerCount();
    },
    getStartElement: () => startEl,
    getTargetElement: () => targetEl,
    getPlayAgainElement: () => playAgainEl,
    getPlayAreaSize: () => ({ width: 200, height: 200 }),
    render(state) {
      renders.push(state);
    }
  };
}

test('a mouse click on the target scores exactly once and relocates it to a new valid position', () => {
  const view = createFakeView();
  const controller = createGameController({ view, random: sequenceRandom([0.1, 0.1, 0.9, 0.9]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  const before = controller.getState().target;

  view.targetEl.dispatchEvent(makeEvent('click'));
  const after = controller.getState();

  assert.equal(after.score, 1);
  assert.notDeepEqual(after.target, before);
});

test('a touch activation on the target scores exactly once and prevents the browser default', () => {
  const view = createFakeView();
  const controller = createGameController({ view, random: sequenceRandom([0.2, 0.2, 0.5, 0.5]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  const touchEvent = makeEvent('touchend');
  view.targetEl.dispatchEvent(touchEvent);

  assert.equal(controller.getState().score, 1);
  assert.equal(touchEvent.defaultPrevented, true);
});

test('keyboard Enter and Space on the target each score exactly once; other keys do not', () => {
  const view = createFakeView();
  const controller = createGameController({ view, random: sequenceRandom([0.3, 0.3, 0.4, 0.4, 0.6, 0.6]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  view.targetEl.dispatchEvent(makeEvent('keydown', { key: 'Enter' }));
  view.targetEl.dispatchEvent(makeEvent('keydown', { key: ' ' }));
  view.targetEl.dispatchEvent(makeEvent('keydown', { key: 'ArrowRight' }));

  assert.equal(controller.getState().score, 2);
});

test('activating Start or Play Again via keyboard Enter or Space begins a round', () => {
  const view = createFakeView();
  const controller = createGameController({ view, random: sequenceRandom([0.5]) });

  view.startEl.dispatchEvent(makeEvent('keydown', { key: 'Enter' }));

  assert.equal(controller.getState().status, gameState.STATUS.PLAYING);
});

test('activating the target outside the Playing state does not change the score', () => {
  const view = createFakeView();
  const controller = createGameController({ view, random: sequenceRandom([0.5]) });

  view.targetEl.dispatchEvent(makeEvent('click'));

  assert.equal(controller.getState().score, 0);
  assert.equal(controller.getState().status, gameState.STATUS.READY);
});

test('reaching zero time stops the timer, transitions to Game Over, and preserves the final score', (t) => {
  t.mock.timers.enable();
  const view = createFakeView();
  const config = { ROUND_DURATION_SECONDS: 2, MIN_TARGET_SIZE_PX: 48, TICK_INTERVAL_MS: 1000, SCORE_PER_HIT: 1 };
  const controller = createGameController({ view, config, random: sequenceRandom([0.5]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  view.targetEl.dispatchEvent(makeEvent('click'));

  t.mock.timers.tick(1000);
  t.mock.timers.tick(1000);

  const state = controller.getState();
  assert.equal(state.status, gameState.STATUS.GAME_OVER);
  assert.equal(state.timeRemaining, 0);
  assert.equal(state.score, 1);
  assert.equal(controller.isTimerRunning(), false);
});

test('activating the target after Game Over does not change the score', (t) => {
  t.mock.timers.enable();
  const view = createFakeView();
  const config = { ROUND_DURATION_SECONDS: 1, MIN_TARGET_SIZE_PX: 48, TICK_INTERVAL_MS: 1000, SCORE_PER_HIT: 1 };
  const controller = createGameController({ view, config, random: sequenceRandom([0.5]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  t.mock.timers.tick(1000);
  assert.equal(controller.getState().status, gameState.STATUS.GAME_OVER);

  view.targetEl.dispatchEvent(makeEvent('click'));

  assert.equal(controller.getState().score, 0);
});

test('restart after Game Over cancels prior timing activity and registers no duplicate listeners', (t) => {
  t.mock.timers.enable();
  const view = createFakeView();
  const config = { ROUND_DURATION_SECONDS: 1, MIN_TARGET_SIZE_PX: 48, TICK_INTERVAL_MS: 1000, SCORE_PER_HIT: 1 };
  const controller = createGameController({ view, config, random: sequenceRandom([0.5]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  t.mock.timers.tick(1000);
  assert.equal(controller.getState().status, gameState.STATUS.GAME_OVER);

  const listenersBefore = view.totalListenerCount();

  view.playAgainEl.dispatchEvent(makeEvent('click'));
  view.playAgainEl.dispatchEvent(makeEvent('click'));

  assert.equal(view.totalListenerCount(), listenersBefore);
  assert.equal(controller.isTimerRunning(), true);
  assert.equal(controller.getState().status, gameState.STATUS.PLAYING);

  t.mock.timers.tick(1000);
  assert.equal(controller.getState().status, gameState.STATUS.GAME_OVER);
  assert.equal(controller.isTimerRunning(), false);
});

test('the game status transitions explicitly through Ready, Playing, and Game Over', (t) => {
  t.mock.timers.enable();
  const view = createFakeView();
  const config = { ROUND_DURATION_SECONDS: 1, MIN_TARGET_SIZE_PX: 48, TICK_INTERVAL_MS: 1000, SCORE_PER_HIT: 1 };
  const controller = createGameController({ view, config, random: sequenceRandom([0.5]) });

  assert.equal(controller.getState().status, gameState.STATUS.READY);

  view.startEl.dispatchEvent(makeEvent('click'));
  assert.equal(controller.getState().status, gameState.STATUS.PLAYING);

  t.mock.timers.tick(1000);
  assert.equal(controller.getState().status, gameState.STATUS.GAME_OVER);
});

test('dispatching a window resize event while Playing causes no error and registers no additional timers or listeners', (t) => {
  t.mock.timers.enable();
  const view = createFakeView();
  const controller = createGameController({ view, random: sequenceRandom([0.5]) });

  view.startEl.dispatchEvent(makeEvent('click'));
  const listenersBefore = view.totalListenerCount();
  const timerWasRunning = controller.isTimerRunning();

  const fakeWindow = new EventTarget();
  assert.doesNotThrow(() => {
    fakeWindow.dispatchEvent(new Event('resize'));
  });

  assert.equal(view.totalListenerCount(), listenersBefore);
  assert.equal(controller.isTimerRunning(), timerWasRunning);
});
